'use strict';
const $=s=>document.querySelector(s);
const paths={menu:'M4 6h16M4 12h16M4 18h16',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',home:'M3 10l9-7 9 7v11h-6v-7H9v7H3z',shorts:'M16 3L6 8a4 4 0 0 0 0 7l2 1-2 1a3 3 0 0 0 3 5l10-6a4 4 0 0 0 0-7l-2-1 2-1a3 3 0 0 0-3-4zM10 9l5 3-5 3z',subscriptions:'M5 3h14M3 7h18M2 11h20v11H2zM10 14l5 3-5 3z',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v6l4 2',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v6l4 2',like:'M8 10l4-7c2 0 3 1 2 4l-1 3h6a2 2 0 0 1 2 2l-2 8H8zM3 10h5v10H3z',playlist:'M3 5h14M3 10h14M3 15h8M16 14l6 4-6 4z',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',share:'M14 3l8 7-8 7v-5c-6 0-9 3-12 7 0-9 5-13 12-13z',save:'M4 4h16v18l-8-5-8 5z',dots:'M12 5h.01M12 12h.01M12 19h.01',theater:'M2 5h20v14H2z',check:'M4 12l5 5L20 6',close:'M6 6l12 12M6 18L18 6',music:'M9 18V5l12-3v13M9 18a3 3 0 1 1-6 0 3 3 0 0 1 6 0M21 15a3 3 0 1 1-6 0 3 3 0 0 1 6 0',learn:'M2 9l10-6 10 6-10 6zM6 12v6l6 3 6-3v-6',fire:'M12 2c2 6 8 7 8 13a8 8 0 0 1-16 0c0-3 2-6 4-8 0 5 2 5 3 4 2-2 1-6 1-9z'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.playlist}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=u=>{try{const x=new URL(u);return x.protocol==='https:'?x.href:''}catch{return ''}};
const read=(key,f)=>{try{return JSON.parse(localStorage.getItem(key))||f}catch{return f}};
const data={saved:read('pt-saved',[]),history:read('pt-history',[]),liked:read('pt-liked',[]),subs:read('pt-subs',[]),playlists:read('pt-playlists',[])};
const state={api:localStorage.getItem('pt-api')||window.PADHAKU_CONFIG?.apiUrl||'',seed:[],items:[],next:'',commentNext:'',route:'home',category:'All',serial:0,current:null,streams:[],saveTarget:null,connected:false};
let toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(){try{for(const k of Object.keys(data))localStorage.setItem('pt-'+k,JSON.stringify(data[k]))}catch{toast('Your browser storage is full. Clear some history to save more videos.')}}
function avatar(v){return `<span class="smallavatar">${safe(v.avatar)?`<img src="${esc(safe(v.avatar))}" alt="" loading="lazy">`:esc((v.channel||v.name||v.author||'P').slice(0,1).toUpperCase())}</span>`}
const count=n=>n==null||n<0?'':new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(n);
function card(v){const stats=[v.views>=0?count(v.views)+' views':'',v.uploaded||''].filter(Boolean).join(' · ');return `<article class="card"><a class="thumbnail" href="#watch=${encodeURIComponent(v.id)}"><img src="${esc(safe(v.thumbnail))}" alt="" loading="lazy"><span class="duration">${esc(v.duration||'Watch')}</span></a><div class="cardbody">${avatar(v)}<div><h3><a href="#watch=${encodeURIComponent(v.id)}">${esc(v.title)}</a></h3><p>${v.channelUrl?`<a class="channel-link" href="#channel=${encodeURIComponent(v.channelUrl)}">${esc(v.channel)}</a>`:esc(v.channel)}${v.verified?' ✓':''}</p><p>${esc(stats)}</p><p class="carddesc">${esc(v.description||'')}</p></div></div><button class="icon cardmenu" data-save="${esc(v.id)}" aria-label="Save ${esc(v.title)}">${icon('dots')}</button></article>`}
function known(id){return [state.current,...state.items,...state.seed,...data.saved,...data.history,...data.liked,...data.playlists.flatMap(p=>p.videos)].filter(Boolean).find(v=>v.id===id)}
function bindCards(root){root.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>openSave(known(b.dataset.save)));root.querySelectorAll('img').forEach(i=>i.onerror=()=>{i.style.visibility='hidden'})}
function list(root,items){root.innerHTML=items.map(card).join('');bindCards(root)}
function empty(title,description){return `<div class="empty">${icon('playlist')}<b>${esc(title)}</b>${esc(description)}</div>`}
function nav(){const links=[['home','Home','home'],['subscriptions','Subscriptions','subscriptions'],['divider'],['history','History','history'],['playlists','Playlists','playlist'],['saved','Watch later','clock'],['liked','Liked videos','like'],['divider'],['q=Music','Music','music'],['q=Science and technology','Science & technology','learn'],['q=UPSC preparation','Learning','learn']];$('#nav').innerHTML=links.map((x,i)=>x[0]==='divider'?'<hr>':`<button class="${state.route===x[0]?'active ':''}${i>6?'extra':''}" data-nav="${esc(x[0])}">${icon(x[2])}<span>${x[1]}</span></button>`).join('')+(data.subs.length?'<hr><h3>Subscriptions</h3>'+data.subs.slice(0,10).map(s=>`<button class="extra" data-channel="${esc(s.url)}">${avatar(s)}<span>${esc(s.name.slice(0,21))}</span></button>`).join(''):'');$('#nav').querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.nav;document.body.classList.remove('navopen')});$('#nav').querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{location.hash='channel='+encodeURIComponent(b.dataset.channel);document.body.classList.remove('navopen')})}
function chips(){const topics=['All','Music','Podcasts','Computer programming','Science','UPSC','NEET','JEE','Business','Gaming','Recently uploaded'];$('#chips').innerHTML=topics.map(t=>`<button class="${state.category===t?'active':''}" data-topic="${esc(t)}">${esc(t)}</button>`).join('');$('#chips').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.category=b.dataset.topic;location.hash=state.category==='All'?'home':'q='+encodeURIComponent(state.category)})}
function banner(){const el=$('#connectionBanner');el.innerHTML=state.connected?'':`${state.api?'Connecting to your extractor. A sleeping server can take a minute to start.':'Live NewPipe server is not connected. Showing a curated collection.'}<button id="bannerSettings">Settings</button>`;if($('#bannerSettings'))$('#bannerSettings').onclick=openSettings}
async function api(path,base=state.api){if(!base)throw Error('Connect your NewPipe server in Settings.');let r;try{r=await fetch(base+path,{signal:AbortSignal.timeout(65000)})}catch(e){throw Error(e.name==='TimeoutError'?'The server took too long. Try again shortly.':'Cannot reach the NewPipe server. Check its URL and allowed origin.')}let j;try{j=await r.json()}catch{throw Error('The server returned an invalid response.')}if(!r.ok)throw Error(j.error||`Request failed (${r.status})`);return j}
async function checkConnection(base=state.api){const j=await api('/api/health',base);if(j.engine!=='NewPipeExtractor')throw Error('This is not a compatible NewPipe API.');return j}
function setItems(items,next=''){state.items=items;state.next=next;list($('#grid'),items);$('#loadMore').hidden=!next;if(!items.length)$('#grid').innerHTML=empty('No videos found','Try a different search.');}
function stopPlayer(){$('#player').replaceChildren();state.current=null;document.body.classList.remove('theater');}
function routeData(){const hash=location.hash.slice(1)||'home',i=hash.indexOf('=');return {name:i<0?hash:hash.slice(0,i),value:i<0?'':decodeURIComponent(hash.slice(i+1))}}
async function route(){let r;try{r=routeData()}catch{location.hash='home';return}const id=++state.serial;stopPlayer();state.route=r.name;$('#browse').hidden=r.name==='watch';$('#watch').hidden=r.name!=='watch';document.body.classList.toggle('watchmode',r.name==='watch');document.body.classList.remove('navopen');$('#browse').classList.toggle('results',r.name==='q');$('#notice').textContent='';$('#channelHeader').replaceChildren();$('#grid').replaceChildren();$('#loadMore').hidden=true;$('#clearHistory').hidden=r.name!=='history';$('#heading').textContent='';nav();chips();banner();window.scrollTo({top:0});if(r.name==='watch'){await watch(r.value,id);return}$('#chips').hidden=!['home','q'].includes(r.name);if(r.name==='home'||r.name==='q'){const q=r.name==='q'?r.value:'science technology education India';$('#query').value=r.name==='q'?r.value:'';if(r.name==='q')$('#heading').textContent='Search results';if(state.api){$('#notice').textContent='Loading videos…';try{const j=await api('/api/search?q='+encodeURIComponent(q));if(id!==state.serial)return;state.connected=true;banner();setItems(j.items,j.next);$('#notice').textContent=''}catch(e){if(id!==state.serial)return;$('#notice').textContent=e.message;$('#grid').innerHTML=empty('Couldn’t load videos','Try another search or check the server in Settings.')}}else{const items=r.name==='home'?state.seed:state.seed.filter(v=>(v.title+' '+v.channel+' '+v.category).toLowerCase().includes(q.toLowerCase()));setItems(items)}return}
 if(['history','saved','liked'].includes(r.name)){const names={history:'Watch history',saved:'Watch later',liked:'Liked videos'};$('#heading').textContent=names[r.name];setItems(data[r.name]);if(!data[r.name].length)$('#grid').innerHTML=empty('Your collection starts here',r.name==='history'?'Videos you watch will appear here.':'Save or like a video to see it here.');return}
 if(r.name==='subscriptions'){$('#heading').textContent='Subscriptions';$('#grid').innerHTML=data.subs.length?data.subs.map(s=>`<a class="playlisttile" href="#channel=${encodeURIComponent(s.url)}">${avatar(s)}<h2>${esc(s.name)}</h2><p>View channel →</p></a>`).join(''):empty('Follow your favourite channels','Open a video or channel and select Subscribe. Subscriptions are saved on this device.');return}
 if(r.name==='playlists'){$('#heading').textContent='Playlists';$('#grid').innerHTML=data.playlists.length?data.playlists.map(p=>`<a class="playlisttile" href="#playlist=${encodeURIComponent(p.id)}">${icon('playlist')}<h2>${esc(p.name)}</h2><p>${p.videos.length} videos · Private on this device</p></a>`).join(''):empty('A place for every interest','Use Save on any video to create your first playlist.');return}
 if(r.name==='playlist'){const p=data.playlists.find(p=>p.id===r.value);$('#heading').textContent=p?.name||'Playlist not found';setItems(p?.videos||[]);return}
 if(r.name==='channel'){$('#notice').textContent='Loading channel…';try{const c=await api('/api/channel?url='+encodeURIComponent(r.value));if(id!==state.serial)return;$('#notice').textContent='';$('#channelHeader').innerHTML=`${safe(c.banner)?`<div class="channelbanner"><img src="${esc(safe(c.banner))}" alt=""></div>`:''}<div class="channelhead">${avatar(c)}<div><h1>${esc(c.name)}${c.verified?' ✓':''}</h1><p>${count(c.subscribers)} subscribers</p><p class="about">${esc(c.description)}</p><button id="channelSubscribe" class="subscribe">${data.subs.some(s=>s.url===c.url)?'Subscribed':'Subscribe'}</button></div></div>`;$('#channelSubscribe').onclick=()=>{toggleSub({url:c.url,name:c.name,avatar:c.avatar});$('#channelSubscribe').textContent=data.subs.some(s=>s.url===c.url)?'Subscribed':'Subscribe'};setItems(c.items,c.next)}catch(e){if(id===state.serial)$('#notice').textContent=e.message}return}
 location.hash='home';}
function toggleSub(c){if(!c.url){toast('Channel details require a live NewPipe connection.');return}data.subs=data.subs.some(s=>s.url===c.url)?data.subs.filter(s=>s.url!==c.url):[c,...data.subs];persist();nav();updateActions()}
function updateActions(){const v=state.current;if(!v)return;$('#like').innerHTML=icon('like')+' '+(data.liked.some(x=>x.id===v.id)?'Liked':'Like');$('#like').classList.toggle('liked',data.liked.some(x=>x.id===v.id));$('#like').setAttribute('aria-pressed',String(data.liked.some(x=>x.id===v.id)));const sub=data.subs.some(s=>s.url===v.channelUrl);$('#subscribe').textContent=sub?'Subscribed':'Subscribe';$('#subscribe').classList.toggle('subscribed',sub);$('#share').innerHTML=icon('share')+' Share';$('#save').innerHTML=icon('save')+' Save'}
function watchMetadata(v){$('#watchTitle').textContent=v.title;document.title=v.title+' - PadhakuTube';$('#watchChannel').innerHTML=avatar(v)+`<span><b>${esc(v.channel||'YouTube')}</b><small>${v.subscribers>=0?count(v.subscribers)+' subscribers':'View channel'}</small></span>`;$('#stats').textContent=[v.views>=0?count(v.views)+' views':'',v.uploaded||''].filter(Boolean).join(' · ');$('#descriptionText').textContent=v.description||'Watch this video from '+(v.channel||'YouTube')+'.';$('#descriptionText').parentElement.classList.remove('expanded');$('#expandDescription').textContent='Show more';updateActions()}
function embedded(){const v=state.current;if(!v)return;$('#player').innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(v.id)}?autoplay=1" title="${esc(v.title)}" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;$('#playState').textContent='YouTube embedded player';$('#quality').hidden=true;$('#speed').hidden=true;$('#fallback').textContent=state.streams.length?'Try NewPipe player':'Embedded player'}
function direct(index=0){const s=state.streams[index],v=state.current;if(!s||!v){embedded();return}const old=$('#player video'),time=old?.currentTime||0,rate=old?.playbackRate||1;const video=document.createElement('video');video.controls=true;video.autoplay=true;video.playsInline=true;video.poster=safe(v.thumbnail);video.src=s.proxyPath?.startsWith('/api/media?')?state.api+s.proxyPath:safe(s.url);video.addEventListener('loadedmetadata',()=>{if(time&&time<video.duration)video.currentTime=time;video.playbackRate=rate});video.onerror=()=>{$('#playState').textContent='Direct playback failed. Try the embedded player.';$('#fallback').textContent='Use embedded player'};$('#player').replaceChildren(video);$('#quality').hidden=false;$('#speed').hidden=false;$('#playState').textContent='NewPipe player';$('#fallback').textContent='Embedded player';$('#quality').innerHTML=state.streams.map((x,i)=>`<option value="${i}" ${i===index?'selected':''}>${esc(x.quality)}</option>`).join('')}
async function watch(videoId,id){if(!/^[\w-]{11}$/.test(videoId)){$('#watchTitle').textContent='Invalid video link';return}let v=known(videoId)||{id:videoId,title:'Loading video…',channel:'',thumbnail:'https://i.ytimg.com/vi/'+videoId+'/hqdefault.jpg'};state.current=v;state.streams=[];watchMetadata(v);embedded();list($('#related'),state.seed.filter(x=>x.id!==v.id));$('#comments').textContent=state.api?'Loading comments…':'Connect your NewPipe server to read comments.';$('#moreComments').hidden=true;if(state.api){$('#playState').textContent='Loading NewPipe streams…';loadComments(videoId,id);try{const j=await api('/api/stream?id='+videoId);if(id!==state.serial)return;v={...v,...j};state.current=v;state.streams=(j.streams||[]).filter(x=>x.mimeType==='video/mp4'||x.mimeType==='video/webm');watchMetadata(v);list($('#related'),j.related?.length?j.related:state.seed.filter(x=>x.id!==v.id));state.items=[v,...(j.related||[])];if(state.streams.length)direct();else{$('#playState').textContent='No combined stream available. Using embedded player.'}}catch(e){if(id!==state.serial)return;$('#playState').textContent='NewPipe unavailable; embedded playback is available.';toast(e.message)}}if(id!==state.serial)return;data.history=[v,...data.history.filter(x=>x.id!==v.id)].slice(0,200);persist()}
function commentHTML(c){return `<article class="comment">${avatar(c)}<div>${c.pinned?'<small>Pinned by creator</small><br>':''}<b>${esc(c.author)}</b><small>${esc(c.published)}</small><p>${esc(c.text)}</p><span class="commentlikes">${c.likes>=0?'♡ '+count(c.likes):''}</span></div></article>`}
async function loadComments(videoId,id,cursor=''){try{const j=await api(cursor?'/api/more?cursor='+encodeURIComponent(cursor):'/api/comments?id='+videoId);if(id!==state.serial)return;if(!cursor)$('#comments').replaceChildren();$('#comments').insertAdjacentHTML('beforeend',j.items.map(commentHTML).join(''));if(!j.items.length&&!cursor)$('#comments').textContent='No comments are available for this video.';state.commentNext=j.next;$('#moreComments').hidden=!j.next}catch(e){if(id===state.serial)$('#comments').textContent='Comments unavailable. '+e.message}}
function openSave(v){if(!v)return;state.saveTarget=v;renderSave();$('#saveDialog').showModal()}
function renderSave(){const v=state.saveTarget;$('#playlistOptions').innerHTML=`<button data-collection="saved">${icon(data.saved.some(x=>x.id===v.id)?'check':'clock')}Watch later</button>`+data.playlists.map(p=>`<button data-collection="${esc(p.id)}">${icon(p.videos.some(x=>x.id===v.id)?'check':'playlist')}${esc(p.name)}</button>`).join('');$('#playlistOptions').querySelectorAll('button').forEach(b=>b.onclick=()=>{const arr=b.dataset.collection==='saved'?data.saved:data.playlists.find(p=>p.id===b.dataset.collection).videos;const i=arr.findIndex(x=>x.id===v.id);if(i<0)arr.push(v);else arr.splice(i,1);persist();renderSave();toast(i<0?'Video saved':'Video removed');if(state.route==='saved')list($('#grid'),data.saved);if(state.route==='playlist'){const p=data.playlists.find(p=>p.id===routeData().value);if(p)list($('#grid'),p.videos)}})}
function openSettings(){$('#apiUrl').value=state.api;$('#connectionStatus').textContent=state.connected?'Connected to NewPipeExtractor.':'Connect your hosted NewPipe API to enable live search.';$('#config').showModal()}
function parseSearch(q){try{const u=new URL(q);if(['www.youtube.com','youtube.com','m.youtube.com','youtu.be'].includes(u.hostname)){const id=u.searchParams.get('v')||(u.hostname==='youtu.be'?u.pathname.slice(1):u.pathname.split('/')[2]);if(id&&/^[\w-]{11}$/.test(id))return 'watch='+id}}catch{}return 'q='+encodeURIComponent(q)}
$('#menu').innerHTML=icon('menu');$('#searchbutton').innerHTML=icon('search');$('#settings').innerHTML=icon('settings');$('#theater').innerHTML=icon('theater');
function theme(){document.body.classList.toggle('dark',localStorage.getItem('pt-theme')==='dark');$('#theme').innerHTML=icon(document.body.classList.contains('dark')?'sun':'moon')}theme();$('#theme').onclick=()=>{localStorage.setItem('pt-theme',document.body.classList.contains('dark')?'light':'dark');theme()};$('#menu').onclick=()=>document.body.classList.toggle(window.innerWidth<=960||state.route==='watch'?'navopen':'collapsed');$('#scrim').onclick=()=>document.body.classList.remove('navopen');$('#settings').onclick=openSettings;$('#profile').onclick=()=>location.hash='playlists';document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#searchform').onsubmit=e=>{e.preventDefault();const q=$('#query').value.trim();if(q){const hash=parseSearch(q);if(location.hash.slice(1)===hash)route();else location.hash=hash}};
$('#loadMore').onclick=async()=>{const button=$('#loadMore'),id=state.serial;button.disabled=true;try{const j=await api('/api/more?cursor='+encodeURIComponent(state.next));if(id===state.serial){const seen=new Set(state.items.map(x=>x.id));setItems([...state.items,...j.items.filter(x=>!seen.has(x.id))],j.next)}}catch(e){toast(e.message)}finally{button.disabled=false}};
$('#moreComments').onclick=async()=>{const b=$('#moreComments');b.disabled=true;await loadComments(state.current.id,state.serial,state.commentNext);b.disabled=false};$('#watchChannel').onclick=()=>{if(state.current?.channelUrl)location.hash='channel='+encodeURIComponent(state.current.channelUrl);else toast('Connect NewPipe to open channel details.')};$('#subscribe').onclick=()=>state.current&&toggleSub({url:state.current.channelUrl,name:state.current.channel,avatar:state.current.avatar});$('#like').onclick=()=>{const v=state.current;if(!v)return;const i=data.liked.findIndex(x=>x.id===v.id);if(i<0)data.liked.push(v);else data.liked.splice(i,1);persist();updateActions();toast(i<0?'Added to your liked videos on this device':'Removed from liked videos')};$('#save').onclick=()=>openSave(state.current);$('#share').onclick=()=>{const v=state.current;if(!v)return;$('#shareUrl').value='https://www.youtube.com/watch?v='+v.id;$('#original').href=$('#shareUrl').value;$('#shareDialog').showModal()};$('#copyShare').onclick=async()=>{try{await navigator.clipboard.writeText($('#shareUrl').value);toast('Link copied')}catch{$('#shareUrl').select();toast('Select and copy the video link.')}};$('#quality').onchange=()=>direct(Number($('#quality').value));$('#speed').onchange=()=>{if($('#player video'))$('#player video').playbackRate=Number($('#speed').value)};$('#fallback').onclick=()=>$('#player video')?embedded():state.streams.length?direct():embedded();$('#theater').onclick=()=>document.body.classList.toggle('theater');$('#expandDescription').onclick=()=>{const open=$('.description').classList.toggle('expanded');$('#expandDescription').textContent=open?'Show less':'Show more'};$('#clearHistory').onclick=()=>{data.history=[];persist();route();toast('Watch history cleared on this device')};
$('#newPlaylist').onsubmit=e=>{e.preventDefault();const name=$('#playlistName').value.trim();if(!name)return;data.playlists.push({id:crypto.randomUUID(),name,videos:[state.saveTarget]});persist();$('#playlistName').value='';renderSave();toast('Playlist created')};
$('#connect').onclick=async()=>{const b=$('#connect');b.disabled=true;try{const base=$('#apiUrl').value.trim().replace(/\/+$/,'');if(!safe(base))throw Error('Enter an HTTPS server URL.');$('#connectionStatus').textContent='Checking server. First startup may take a minute…';const j=await checkConnection(base);state.api=base;state.connected=true;localStorage.setItem('pt-api',base);$('#connectionStatus').textContent='Connected. NewPipe '+j.version+' is ready.';banner();route()}catch(e){$('#connectionStatus').textContent=e.message}finally{b.disabled=false}};$('#disconnect').onclick=()=>{state.api='';state.connected=false;localStorage.removeItem('pt-api');$('#connectionStatus').textContent='Disconnected. Using the curated collection.';route()};
window.addEventListener('hashchange',route);document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='/'){e.preventDefault();$('#query').focus()}const v=$('#player video');if(!v)return;if(e.key==='k'||e.key===' '){e.preventDefault();v.paused?v.play():v.pause()}if(e.key==='ArrowRight')v.currentTime+=5;if(e.key==='ArrowLeft')v.currentTime=Math.max(0,v.currentTime-5);if(e.key==='m')v.muted=!v.muted;if(e.key==='f')v.requestFullscreen?.()});
(async()=>{try{state.seed=await(await fetch('curated.json')).json()}catch{}route();if(state.api){try{await checkConnection();state.connected=true;banner()}catch(e){state.connected=false;banner();toast(e.message)}}})();
